import axios from 'axios';
import { API_CONFIG } from '../config/apiConfig';

const API_BASE = `${API_CONFIG.BASE_URL}/monitoring`;

const monitoringService = {
  /**
   * Start monitoring for an exam session
   */
  async startMonitoring(examSessionId) {
    try {
      const response = await axios.post(`${API_BASE}/start`, {
        exam_session_id: examSessionId
      });
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  /**
   * Stop monitoring for an exam session
   */
  async stopMonitoring(examSessionId) {
    try {
      const response = await axios.post(`${API_BASE}/stop`, {
        exam_session_id: examSessionId
      });
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  /**
   * Get monitoring status
   */
  async getMonitoringStatus() {
    try {
      const response = await axios.get(`${API_BASE}/status`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  /**
   * Get alerts for an exam session
   */
  async getAlerts(examSessionId) {
    try {
      const response = await axios.get(`${API_BASE}/alerts/${examSessionId}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  }
};

export default monitoringService;
